import{_ as l,b as a,c as s,g as t}from"./chunks/framework.86O3EbG5.js";const e="/images/build-a-llm/ch04-1.png",p="/images/build-a-llm/ch04-2.png",g=JSON.parse('{"title":"从零构建大模型（四）","description":"","frontmatter":{"title":"从零构建大模型（四）","subTitle":"从头实现GPT模型进行文本生成","author":"oasis","tags":["llm"]},"headers":[],"relativePath":"articles/ai/books/build-a-llm/4.md","filePath":"articles/ai/books/build-a-llm/4.md"}'),o={name:"articles/ai/books/build-a-llm/4.md"};function n(d,i,r,c,m,h){return a(),s("div",null,[...i[0]||(i[0]=[t('<p>Transformer 块包含如下部分：</p><ol><li>层归一化</li><li>GELU 激活函数</li><li>前馈神经网络</li><li>快接连接</li></ol><h2 id="层归一化" tabindex="-1">层归一化</h2><p>层归一化的主要思想是调整神经网络层的激活（输出），使其均值为0且方差（单位方差）为1。这种调整有助于加速权重的有效收敛，并确保训练过程的一致性和可靠性。</p><p>层归一化通常在多头注意力模块的前后进行，同时层归一化还应用于最终输出层之前。</p><p>均值和方差的计算方法：</p><p><img src="'+e+`" alt="img.png"></p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">样本特征：x = [2, 4, 6, 8]  (d=4)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">设：ε = 0.00001, γ = [1,1,1,1], β = [0,0,0,0]</span></span></code></pre></div><p>层归一化是在特征维度上进行归一化。层归一化是对每个输入独立进行归一化，不受批次大小的限制，因此更灵活和稳定。在资源受限的环境中部署模型时尤为重要。</p><h2 id="gelu-激活函数" tabindex="-1">GELU 激活函数</h2><p>GELU 激活函数更为复杂且平滑，结合了高斯分布和sigmoid门控线单元，能提升深度学习模型的性能。</p><p><img src="`+p+'" alt="img.png"></p><p>GELU 的平滑特性可以在训练过程中带来更好的优化效果，因为它允许模型参数进行更细微的调整。</p><p>书中 FeedForward 模块是一个小型神经网络(前馈神经网络)，有两个线性层和一个 GELU 激活函数组成。</p><p>第一个线性层用来扩展可表示的空间，第二个线性层用来缩放到原始大小。输入和输出维度的一致性简化了架构，在后续堆叠多个层时无须调整维度，这样可以增强扩展能力。</p><h2 id="快捷连接" tabindex="-1">快捷连接</h2><p>快接连接的目的是避免梯度消失，在训练过程中，梯度反向传播时逐渐变小，导致网络层难以有效训练。快捷连接通过跳过一个或多个层，为梯度在网络中的流动提供了一条可替代且更短的路径。</p><h2 id="文本生成的过程" tabindex="-1">文本生成的过程</h2><ol><li>将文本输入编码为词元 ID</li><li>GPT 模型返回一个由向量组成的矩阵，其中每个向量有 50257 维度</li><li>提取最后一个向量，它对应于 GPT 模型应该生成的下一个词元</li><li>使用 softmax 函数将 logits 转换为概率分布</li><li>确定最大值的索引，该位置代表词元 ID</li><li>将词元追加到上一轮输入中，进行下一轮输入</li><li>如果最大的元素位于第 257 位，那么我们就得到了词元 ID 257</li></ol>',19)])])}const b=l(o,[["render",n]]);export{g as __pageData,b as default};
